SELECT BASE_RULE_ID baseRuleId, EFF_DATE effDate, RATE_TYPE rateType, RATE*100 rate, INDEX_ID indexId, INDEX_SOURCE indexSource, COEFFICIENT coefficient, SPREAD_RATE*100 spreadRate, RESET_TYPE resetType, FINPROD_ID finprodId, BRANCH branch, REMARK remark, BASE_RULE_TYPE baseRuleType, PUBLISH_TYPE publishType, RATE_LOWER rateLower, RATE_LIMIT rateLimit FROM FIN_BASE_RULE_INFO where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and EFF_DATE = to_date(#{effDate,jdbcType=VARCHAR},'yyyy-MM-dd')
